diff --git a/src/mat.c b/src/mat.c
index e28167f..3542a77 100644
--- a/src/mat.c
+++ b/src/mat.c
@@ -1333,6 +1333,8 @@ Mat_VarCreate(const char *name, enum matio_classes class_type, enum matio_types
     }
     matvar->class_type = class_type;
     matvar->data_type = data_type;
+    if ( class_type == MAT_C_CELL && rank == 3 && NULL != matvar->internal )
