diff --git a/src/matvar_cell.c b/src/matvar_cell.c
index e57cfc3..1a69fbf 100644
--- a/src/matvar_cell.c
+++ b/src/matvar_cell.c
@@ -107,7 +107,14 @@ Mat_VarGetCells(const matvar_t *matvar, const int *start, const int *stride, con
                 free(cells);
                 return NULL;
             }
-            cells[i + j] = *((matvar_t **)matvar->data + I);
+            {
+                size_t elem = (size_t)I;
+                if ( matvar->rank == 3 && NULL != matvar->internal &&
+                     matvar->internal->num_fields > 1 &&
+                     matvar->data_size > (int)sizeof(matvar_t *) )
+                    elem *= (size_t)matvar->data_size / sizeof(matvar_t *);
