diff --git a/src/matvar_cell.c b/src/matvar_cell.c
--- a/src/matvar_cell.c
+++ b/src/matvar_cell.c
@@ -33,8 +33,17 @@
     if ( err )
         return NULL;

-    if ( 0 <= index && (size_t)index < nelems )
-        cell = *((matvar_t **)matvar->data + index);
+    if ( 0 <= index && (size_t)index < nelems ) {
+        const char *base = (const char *)matvar->data;
+        size_t stride = sizeof(matvar_t *);
+        if ( matvar->class_type == MAT_C_CELL && matvar->rank == 3 ) {
+            if ( matvar->data_size > (int)sizeof(matvar_t *) )
+                stride = (size_t)matvar->data_size;
+            else if ( NULL != matvar->internal && matvar->internal->num_fields > 1 )
+                stride = (size_t)matvar->internal->num_fields * sizeof(matvar_t *);
+        }
+        cell = *(matvar_t **)(base + (size_t)index * stride);
+    }

     return cell;
 }

diff --git a/src/mat.c b/src/mat.c
--- a/src/mat.c
+++ b/src/mat.c
@@ -1536,6 +1536,14 @@
         matvar->mem_conserve = 0;
     }

+    if ( matvar->class_type == MAT_C_CELL && matvar->rank == 3 && matvar->data_size > 0 ) {
+        size_t nbytes = 0;
+        if ( matvar->nbytes > 0 && !Mul(&nbytes, matvar->nbytes, 2) )
+            matvar->nbytes = nbytes;
+        if ( matvar->data_size <= INT_MAX / 2 )
+            matvar->data_size *= 2;
+    }
+
     return matvar;
 }
